  if (!shell)
    return message.channel.send(
      'Sorry, we are not able to find your default shell.\nPlease set `process.env.SHELL`.'
    )

  const msg = new ProcessManager(message, `$ ${message.data.args}\n`, parent, {
    lang: 'ansi'
  })
  await msg.init()

